package com.salespunch360.mobile.ui.account.money
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun MoneyScreen(initialMode:String,padding:PaddingValues,vm:AccountMoneyViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;LaunchedEffect(initialMode){vm.show(initialMode)};val rows=when(s.mode){"accounts"->s.data["dashboard"]?.jsonObject?.array("accounts").orEmpty();"transfers"->s.data.array("transfers");"owners"->s.data.array("ownerTransactions");"loans"->s.data.array("loans");else->emptyList()};Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){LazyRow{items(listOf("accounts","transfers","owners","loans")){m->FilterChip(s.mode==m,{vm.show(m)},{Text(if(m=="owners")"Capital & drawings" else m.replaceFirstChar{it.uppercase()})})}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.End){IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};if(s.mode=="owners")TextButton({vm.create("owner-setup")}){Text("Set up owner")};FilledIconButton({vm.create(s.mode)}){Icon(Icons.Default.Add,"New")}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(rows){e->val x=e.jsonObject;ListItem(headlineContent={Text(x.str("name").ifBlank{x.str("lender").ifBlank{x.str("type")}},fontWeight=FontWeight.Bold)},supportingContent={Text(listOf(x.str("transferDate").take(10),x.str("transactionDate").take(10),x.str("startDate").take(10),x.str("reference")).filter{it.isNotBlank()}.joinToString(" · "))},trailingContent={Column{Text("₹${x.str("balance").ifBlank{x.str("amount").ifBlank{x.str("principal")}}}");if(s.mode=="loans")TextButton({vm.loanPayment(x)}){Text("Repay")};if(s.mode=="accounts"&&x["isActive"]?.jsonPrimitive?.booleanOrNull==true)TextButton({vm.disableAccount(x.str("id"))}){Text("Deactivate")}}},modifier=if(s.mode=="accounts")Modifier.clickable{vm.editAccount(x)}else Modifier)}}};s.editing?.let{MoneyEditor(it,s.data,s.selected,vm::close,vm::save)}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun MoneyEditor(kind:String,data:JsonObject,selected:JsonObject?,close:()->Unit,save:(String,JsonObject)->Unit){var branch by remember{mutableStateOf("")};var source by remember{mutableStateOf("")};var destination by remember{mutableStateOf("")};var owner by remember{mutableStateOf("")};var name by remember{mutableStateOf(selected?.str("name").orEmpty())};var type by remember{mutableStateOf(if(kind=="owners")"INVESTMENT" else selected?.str("type").orEmpty().ifBlank{"BANK"})};var amount by remember{mutableStateOf("")};var interest by remember{mutableStateOf("0")};var charges by remember{mutableStateOf("0")};var date by remember{mutableStateOf(java.time.LocalDate.now().toString())};var reference by remember{mutableStateOf("")};val accounts=data["dashboard"]?.jsonObject?.array("accounts").orEmpty();AlertDialog(onDismissRequest=close,title={Text(kind.replace('-',' ').replaceFirstChar{it.uppercase()})},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){if(kind=="owner-setup"){item{Pick("Owner user",owner,data.array("users")){owner=it}};item{Pick("Branch",branch,data.array("branches")){branch=it}}}else if(kind=="accounts"){item{OutlinedTextField(name,{name=it},label={Text("Account name")})};item{PickText("Account type",type,listOf("CASH","BANK","WALLET","UPI","OTHER")){type=it}};if(selected==null)item{Pick("Branch (optional)",branch,data.array("branches")){branch=it}}}else{item{Pick("Branch",branch,data.array("branches")){branch=it}};if(kind=="transfers"){item{Pick("Source account",source,accounts){source=it}};item{Pick("Destination account",destination,accounts){destination=it}}}else{item{Pick("Money account",source,accounts){source=it}}};if(kind=="owners"){item{Pick("Owner",owner,data.array("owners")){owner=it}};item{PickText("Type",type,listOf("INVESTMENT","WITHDRAWAL","OWNER_LOAN")){type=it}}};if(kind=="loans"){item{OutlinedTextField(name,{name=it},label={Text("Lender")})};item{OutlinedTextField(interest,{interest=it},label={Text("Interest rate")})}};if(kind=="loan-payments"){item{OutlinedTextField(interest,{interest=it},label={Text("Interest paid")})};item{OutlinedTextField(charges,{charges=it},label={Text("Charges")})}};item{OutlinedTextField(amount,{amount=it},label={Text(if(kind=="loan-payments")"Principal paid" else "Amount")})};item{OutlinedTextField(date,{date=it},label={Text("Date")})};item{OutlinedTextField(reference,{reference=it},label={Text("Reference")})}}}},confirmButton={Button(enabled=(kind=="accounts"&&name.isNotBlank())||(kind=="owner-setup"&&owner.isNotBlank()&&branch.isNotBlank())||(kind!="accounts"&&kind!="owner-setup"&&source.isNotBlank()&&amount.isNotBlank()),onClick={save(kind,buildJsonObject{if(kind=="accounts"){put("name",name);if(selected==null){put("type",type);branch.takeIf{it.isNotBlank()}?.let{put("branchId",it)}}}else if(kind=="owner-setup"){put("userId",owner);put("branchId",branch)}else{put("branchId",branch);put("moneyAccountId",source);put("reference",reference);put("idempotencyKey",java.util.UUID.randomUUID().toString());when(kind){"transfers"->{put("sourceAccountId",source);put("destinationAccountId",destination);put("transferDate",date);put("amount",amount)};"owners"->{put("ownerFinancialAccountId",owner);put("type",type);put("transactionDate",date);put("amount",amount)};"loans"->{put("lender",name);put("loanType","TERM");put("principal",amount);put("interestRate",interest);put("startDate",date)};"loan-payments"->{put("loanId",selected?.str("id").orEmpty());put("paymentDate",date);put("principal",amount);put("interest",interest);put("charges",charges)}}}})}){Text("Confirm on server")}},dismissButton={TextButton(close){Text("Cancel")}})}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun Pick(label:String,value:String,values:List<JsonElement>,set:(String)->Unit){var open by remember{mutableStateOf(false)};val selected=values.map{it.jsonObject}.firstOrNull{it.str("id")==value};ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(selected?.str("name")?.ifBlank{null}?:selected?.str("lender").orEmpty(),{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){values.forEach{e->val x=e.jsonObject;DropdownMenuItem({Text(x.str("name").ifBlank{x.str("lender")})},{set(x.str("id"));open=false})}}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun PickText(label:String,value:String,values:List<String>,set:(String)->Unit){var open by remember{mutableStateOf(false)};ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(value,{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){values.forEach{v->DropdownMenuItem({Text(v)},{set(v);open=false})}}}}
